from dataclasses import dataclass

@dataclass
class TranslationRequest:
    text: str
    source_language_code: str
    target_language_code: str

@dataclass
class TranslationResponse:
    translated_text: str
    source_language_code: str
    target_language_code: str

import boto3

def get_translate_client():
    return boto3.client("translate")

import boto3

def summarize_quality_issues(translated_text: str, target_language_code: str) -> dict:
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=translated_text,
        LanguageCode=target_language_code
    )
    return {
        "sentiment": response['Sentiment'],
        "sentiment_score": response['SentimentScore']
    }

import boto3

def unsafe_copy_check(text: str, language_code: str) -> dict:
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_pii_entities(
        Text=text,
        LanguageCode=language_code
    )
    return {
        "pii_entities": response['Entities']
    }

import boto3

def localized_audio_preview(text: str, language_code: str, voice_id: str = 'Joanna') -> bytes:
    polly_client = boto3.client('polly')
    response = polly_client.synthesize_speech(
        Text=text,
        OutputFormat='mp3',
        VoiceId=voice_id,
        LanguageCode=language_code # Not all voices support all languages, so this might need adjustment
    )
    return response['AudioStream'].read()
